WITH johnstown_area AS (
  SELECT ST_GeomFromText('POLYGON ((-85.189732 42.420649, -85.279669 42.419969, -85.279916 42.419967, -85.29958 42.419801, -85.307808 42.419733, -85.308012 42.463589, -85.30791 42.50005, -85.30798 42.50005, -85.308104 42.507867, -85.190633 42.508339, -85.189732 42.420649))', 4326)::geometry AS geom
)
SELECT MAX(rast_val) AS highest_elevation
FROM (
  SELECT ST_Value(rast, 1, (ST_DumpAsPolygons(ST_Clip(rast, 1, geom, TRUE))).geom) AS rast_val
  FROM public.dem_us, johnstown_area
  WHERE ST_Intersects(rast, geom)
) subquery;

